#!/usr/bin/env node
/**
 * Produce the artifacts the backend needs to deploy WITHOUT cdk at the user's runtime, and
 * embed them in a generated TS module the backend imports:
 *
 *   infra/src/template.ts  ──esbuild──▶ evaluate ──▶ backend/src/generated/backend-bundle.ts
 *   lambdas/src/{receiver,portal}.ts ──esbuild──▶ deterministic zip ──▶ (same module)
 *
 * `templateKey` and `lambdaCodeKey` are content-addressed — hashes of the bytes — so the
 * backend can tell "the stack already runs exactly this" from "the app shipped something
 * new", and so CloudFormation's NO_CHANGE can be cross-checked rather than trusted.
 *
 * ⚠️  STALE-BUILD TRAP (CLAUDE.md gotcha #1): backend/index.cjs EMBEDS this output. After any
 *     change under infra/ or lambdas/ you must rebuild AND fully restart AgentsPoppy, or the
 *     deploy silently reports NO_CHANGE with the old code. `npm run build:backend` runs this
 *     first (prebuild:backend) so the two can't drift.
 *
 * Run from the repo root:  npm run gen:backend
 */
import * as esbuild from "esbuild";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { tmpdir } from "node:os";
import { deterministicZip } from "./lib/deterministic-zip.mjs";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const genDir = join(root, "backend", "src", "generated");

/** The two Lambda handlers that share one content-addressed zip. */
const HANDLERS = ["receiver", "portal"];

const git = (args) => {
  try {
    return execFileSync("git", args, { cwd: root }).toString().trim();
  } catch {
    return "";
  }
};

async function main() {
  // 1. Bundle + evaluate the template builder. (It's TypeScript, and it's the single source
  //    of truth for the stack — we never hand-maintain a parallel JSON copy.)
  console.log("[1/3] evaluate infra/src/template.ts");
  const staging = join(tmpdir(), `ap-infra-${process.pid}`);
  mkdirSync(staging, { recursive: true });
  const outfile = join(staging, "template.mjs");
  await esbuild.build({
    entryPoints: [join(root, "infra", "src", "template.ts")],
    outfile,
    bundle: true,
    platform: "node",
    format: "esm",
    target: "node20",
    logLevel: "warning",
  });
  const { buildTemplate, STACK_NAME, TABLE_NAME } = await import(pathToFileURL(outfile).href);
  rmSync(staging, { recursive: true, force: true });

  // Stable key order + 2-space indent: the template builder is pure, so these bytes (and
  // therefore templateKey) are identical on every machine at the same commit.
  const templateJson = JSON.stringify(buildTemplate(), null, 2);
  const templateKey = `template-${createHash("sha256").update(templateJson).digest("hex").slice(0, 16)}`;

  // 2. Bundle each Lambda into ONE CJS file, then a deterministic zip. The AWS SDK is
  //    provided by the nodejs20.x runtime, so we mark it external — that keeps the zip tiny
  //    and avoids shipping a second copy of the SDK.
  console.log("[2/3] esbuild + zip the receiver and portal Lambdas");
  const stage = join(tmpdir(), `ap-lambda-${process.pid}`);
  mkdirSync(stage, { recursive: true });
  const shared = {
    bundle: true,
    platform: "node",
    target: "node20",
    format: "cjs",
    minify: true, // reproducibility: strips module-boundary comments that encode install paths
    legalComments: "none",
    external: ["@aws-sdk/*"],
    logLevel: "warning",
  };
  const built = {};
  for (const name of HANDLERS) {
    const out = join(stage, `${name}.js`);
    await esbuild.build({ ...shared, entryPoints: [join(root, "lambdas", "src", `${name}.ts`)], outfile: out });
    built[name] = readFileSync(out);
  }
  rmSync(stage, { recursive: true, force: true });

  // Content-addressed over BOTH handlers — changing only the portal must still flip the key,
  // or CloudFormation reports NO_CHANGE and silently keeps serving the old page.
  const hash = createHash("sha256");
  for (const name of HANDLERS) hash.update(built[name]);
  const lambdaCodeKey = `lambdas-${hash.digest("hex").slice(0, 16)}.zip`;
  // Fixed mtime (HEAD commit time) → byte-identical archive on any machine at the same commit.
  const epoch = Number(process.env.SOURCE_DATE_EPOCH || git(["log", "-1", "--format=%ct"]) || 0);
  const lambdaZip = deterministicZip(
    HANDLERS.map((name) => ({ name: `${name}.js`, data: built[name] })),
    epoch,
  );

  // 3. Emit the module the backend imports. Git-ignored: it is a build output, and committing
  //    it would let it drift from infra/ + lambdas/.
  console.log("[3/3] generate backend/src/generated/backend-bundle.ts");
  mkdirSync(genDir, { recursive: true });
  writeFileSync(
    join(genDir, "backend-bundle.ts"),
    [
      "// AUTO-GENERATED by scripts/build-backend-bundle.mjs — do not edit (git-ignored).",
      "// Rebuild with `npm run gen:backend` after ANY change under infra/ or lambdas/.",
      `export const stackName = ${JSON.stringify(STACK_NAME)};`,
      `export const tableName = ${JSON.stringify(TABLE_NAME)};`,
      `export const templateKey = ${JSON.stringify(templateKey)};`,
      `export const templateJson = ${JSON.stringify(templateJson)};`,
      `export const lambdaCodeKey = ${JSON.stringify(lambdaCodeKey)};`,
      `export const lambdaZipBase64 = ${JSON.stringify(lambdaZip.toString("base64"))};`,
      `export const sourceCommit = ${JSON.stringify(git(["rev-parse", "HEAD"]))};`,
      "",
    ].join("\n"),
  );

  console.log(
    `\n✅ backend bundle ready (${templateKey}, template ${(templateJson.length / 1024).toFixed(1)} KB; ` +
      `${lambdaCodeKey}, zip ${(lambdaZip.length / 1024).toFixed(0)} KB)`,
  );
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
